import{z as s,x as n,o as A,c as o,q as e,j as t,D as a,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"性能建模","description":"","frontmatter":{"title":"性能建模","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-performance-modeling.md","filePath":"llm/dist-performance-modeling.md","lastUpdated":1791063341000}'),p={name:"llm/dist-performance-modeling.md"};function d(m,E,D,P,F,h){const B=n("Mermaid");return A(),o("div",null,[E[2]||(E[2]=e('<h1 id="性能建模" tabindex="-1">性能建模 <a class="header-anchor" href="#性能建模" aria-label="Permalink to &quot;性能建模&quot;">​</a></h1><div class="epigraph"><p>性能建模的用处是在开机之前排除一半的配置；模型不必准到预测，够到排序就行。</p><footer>—— 据 Huang 等 2019 与 Narayanan 等 2021 的分析口径整理</footer></div><p><a href="/llm/dist-debugging">上一课</a>管跑起来之后的事；本课管开跑之前。前面各课给了单项机制——四轴的通信账、重叠的收益式、拓扑的链路容量、显存的三栏清单——本课把它们合成一个能算的模型：给定模型、集群与并行配置，在开跑之前估计 step time 与显存峰值，用它做配置搜索。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有模型时，配置选择靠网格试跑，每次试跑是小时级到天级的成本，而候选配置的空间是各维并行度的乘积，动辄上千。模型的价值是把空间先除以十：解析式排掉明显劣的与明显不可行的，剩下的交给实测。难点是「够准」：气泡、重叠、峰值三项要有解析式，实现效率类系数允许误差，识别哪些项必须准、哪些项可以糊，是建模的第一判断。</p><h3 id="三段式" tabindex="-1">三段式 <a class="header-anchor" href="#三段式" aria-label="Permalink to &quot;三段式&quot;">​</a></h3><p>计算段：每层 FLOPs 约为参数量乘批乘序列的两倍量级，GEMM 时间按峰值算力乘一个实现效率系数折算，系数用一两次小规模实测拟合。通信段：按第一课对照表的原语体积，乘第 4 课的重叠结构（可遮的进 max，不可遮的进和），除以第 5 课的链路有效带宽，加 \\(\\alpha\\) 启动项。气泡段：PP 的气泡占比按 \\((P-1)/(M+P-1)\\) 的 GPipe 口径起算，1F1B 与交错调度的修正见<a href="/llm/1f1b-interleaved">1F1B 与交错流水</a>；TP 的不可遮层内交换单列，不混进气泡。三段合成 step time，显存峰值直接复用上一课的清单——两张表一次出。</p><p><span class="marginnote">排序为什么比预测稳：实现效率这类系数在配置之间近似共享，做比较时分子分母同时出现，误差约掉大半。所以模型输出「配置 A 比配置 B 快三成」可信，「配置 A 绝对 380 毫秒」要打折。</span></p>',8)),(A(),t(i,null,{default:a(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22step%20time%20%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20C%5B%22%E8%AE%A1%E7%AE%97%E6%AE%B5%3A%20%E5%B1%82%20FLOPs%20%2F%20%E5%B3%B0%E5%80%BC%E7%AE%97%E5%8A%9B%20%C3%97%20%E5%AE%9E%E7%8E%B0%E6%95%88%E7%8E%87%22%5D%0A%20%20ST%20--%3E%20M%5B%22%E9%80%9A%E4%BF%A1%E6%AE%B5%3A%20%E5%8F%AF%E9%81%AE%E9%A1%B9%E8%BF%9B%20max%2C%20%E4%B8%8D%E5%8F%AF%E9%81%AE%E9%A1%B9%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20ST%20--%3E%20B%5B%22%E6%B0%94%E6%B3%A1%E6%AE%B5%3A%20PP%20%E6%8C%89%20(P-1)%2F(M%2BP-1)%20%E8%B5%B7%E7%AE%97%22%5D%0A%20%20M%20--%3E%20M1%5B%22%E5%8F%AF%E9%81%AE%3A%20DP%20%E5%BD%92%E7%BA%A6%E7%AD%89%2C%20%E8%97%8F%E8%BF%9B%E8%AE%A1%E7%AE%97%E6%97%B6%E9%97%B4%E9%87%8C%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E4%B8%8D%E5%8F%AF%E9%81%AE%3A%20TP%20%E5%B1%82%E5%86%85%E4%BA%A4%E6%8D%A2%2C%20%E9%99%A4%E9%93%BE%E8%B7%AF%E5%B8%A6%E5%AE%BD%E5%86%8D%E5%8A%A0%20%CE%B1%20%E5%90%AF%E5%8A%A8%E9%A1%B9%22%5D%0A%20%20C%20--%3E%20SUM%5B%22%E4%B8%89%E6%AE%B5%E7%9B%B8%E5%8A%A0%20%3D%20%E9%A2%84%E6%B5%8B%20step%20time%2C%20%E4%BE%9B%E9%85%8D%E7%BD%AE%E6%8E%92%E5%BA%8F%22%5D%0A%20%20B%20--%3E%20SUM%0A%20%20M1%20--%3E%20SUM%0A%20%20M2%20--%3E%20SUM%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">代个数字看气泡公式：PP 度 \\(P=8\\)、微批 \\(M=32\\) 时，气泡占比约 \\((8-1)/(32+8-1) = 7/39 \\approx 18\\%\\)；微批加到 128，降到约 \\(7/135 \\approx 5\\%\\)——这就是「微批越多气泡越小」，代价是激活显存与全局 batch 一起变大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工作流四步：第一步输入固化——模型结构、卡型实测带宽与算力（不抄规格表）、并行候选集；第二步可行性过滤——显存清单过一遍，整除约束过一遍，斩掉大半；第三步解析排序——剩余配置按模型 step time 排序，取前几名；第四步实测校准——前几名上机，用实测回头修系数（通信有效率、实现效率、气泡修正），模型进入下一轮更准。MoE 配置在计算段加专家负载项：按路由统计的热度分布算最忙专家的时间，不用均值。跨 DC 或广域项按第 7 课的结构单独成段。</p><p><span class="marginnote">初学者容易拿规格表带宽直接当有效带宽去除；实际跨节点有效带宽常只有标称的六到八成，且随消息大小变。规格表用来定上限，系数要靠一两次小规模实测标定，模型才排得准。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么解析式能先于实测给出排序：step time 的主导项由「哪一段不可遮、不可并行」决定，主导项的量级由体积公式与链路带宽决定，两者都可以纸面算出；实现细节只修正常数，不改变量级序。模型什么时候失效：瓶颈落在解析式没建模的地方——数据管道、落后者尾延迟、故障恢复期、MoE 负载漂移；失效的信号是「实测与模型差出常数倍」，这时先补建模项而不是调系数。扩展律视角：固定其余维缩一维，从公式里读出每维的饱和点（TP 撞 NVLink 域、PP 撞气泡下限、DP 撞全局 batch），与第一课的缩放极限对照——模型把极限从口诀变成数字。</p><p><span class="marginnote">\\(\\alpha\\) 启动项可以类比快递的起步价：不管包裹多重，先收一笔固定费用。消息越小，这笔固定开销占比越高——所以「多次小交换」在慢链路上最吃亏，建模时小消息不能只算带宽账。</span></p>',7)),(A(),t(i,null,{default:a(()=>[r(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%3A%20%E6%A8%A1%E5%9E%8B%20%2F%20%E5%AE%9E%E6%B5%8B%E5%B8%A6%E5%AE%BD%E4%B8%8E%E7%AE%97%E5%8A%9B%20%2F%20%E5%80%99%E9%80%89%E9%9B%86%22%5D%20--%3E%20FEAS%5B%22%E5%8F%AF%E8%A1%8C%E6%80%A7%E8%BF%87%E6%BB%A4%3A%20%E6%98%BE%E5%AD%98%E6%B8%85%E5%8D%95%20%2B%20%E6%95%B4%E9%99%A4%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20FEAS%20--%3E%20RANK%5B%22%E8%A7%A3%E6%9E%90%E6%8E%92%E5%BA%8F%3A%20%E8%AE%A1%E7%AE%97%E6%AE%B5%20%2B%20%E9%80%9A%E4%BF%A1%E6%AE%B5%20%2B%20%E6%B0%94%E6%B3%A1%E6%AE%B5%22%5D%0A%20%20RANK%20--%3E%20TOP%5B%22%E5%8F%96%E5%89%8D%E5%87%A0%E5%90%8D%E4%B8%8A%E6%9C%BA%E5%AE%9E%E6%B5%8B%22%5D%0A%20%20TOP%20--%3E%20CAL%5B%22%E7%94%A8%E5%AE%9E%E6%B5%8B%E4%BF%AE%E7%B3%BB%E6%95%B0%3A%20%E9%80%9A%E4%BF%A1%E6%9C%89%E6%95%88%E7%8E%87%20%2F%20%E5%AE%9E%E7%8E%B0%E6%95%88%E7%8E%87%20%2F%20%E6%B0%94%E6%B3%A1%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20CAL%20--%3E%7C%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%7C%20RANK%0A%20%20TOP%20--%3E%20DECIDE%5B%22%E5%9B%BA%E5%AE%9A%E9%85%8D%E7%BD%AE%2C%20%E5%87%BA%20MFU%20%E9%A2%84%E6%9C%9F%E4%B8%8E%E6%98%BE%E5%AD%98%E4%BD%99%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型不含故障与恢复的折损（容错课的账），不含损失质量（MFU 课的边界重申）；跨代硬件外推要重标带宽与算力比，异构集群按第 6 课分账后逐设备建小模型再取 max。经验值（MFU 高位、气泡修正）当先验不当定理。模型是文档资产：与显存清单同库维护，集群拓扑一变，通信段重标。最后一条边界：模型替你排除，不替你决定——最终配置仍要一次真实试跑验证 loss 与吞吐同对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>建模的价值是排序与排除，不是绝对预测；实现效率系数共享使排序比数字稳。</li><li>三段式：计算（FLOPs 乘实现效率）、通信（体积乘重叠结构除链路带宽加启动项）、气泡（PP 口径加 TP 单列）。</li><li>工作流：固化输入、可行性过滤、解析排序、实测校准，系数随实测迭代。</li><li>失效信号是实测差出常数倍：先补建模项（数据、尾延迟、负载漂移）再调系数。</li><li>出处：Huang 等，GPipe，2019 的气泡口径；Narayanan 等 2021 的并行分析；显存清单与本课程前课联动。</li></ul>',4))])}const T=s(p,[["render",d]]);export{c as __pageData,T as default};
